function squadPage(){let avg=(players.reduce((s,p)=>s+p.rating,0)/players.length).toFixed(1);return `<div class="page-head"><div><div class="eyebrow">First team · ${players.length} players</div><h1>The squad</h1><p>Know your players. Build the team that gets results.</p></div><button class="btn primary" onclick="switchPage('Tactics')">Set up team&nbsp; →</button></div><div class="squad-summary"><div class="summary-chip"><span>Squad size</span><strong>${players.length} <small class="muted" style="font-size:10px">players</small></strong></div><div class="summary-chip"><span>Average rating</span><strong>${avg}<small class="muted" style="font-size:10px"> / 99</small></strong></div><div class="summary-chip"><span>Squad morale</span><strong>${state.morale}<small class="muted" style="font-size:10px">%</small></strong></div><div class="summary-chip"><span>Transfer budget</span><strong>€${state.budget.toFixed(1)}m</strong></div></div><section class="panel"><div class="panel-pad"><div class="panel-heading"><div><h2>First team</h2><span class="muted" style="font-size:10px">Select a player to view their profile</span></div><div class="toolbar"><select class="select" onchange="filterSquad(this.value)"><option value="all">All positions</option><option>GK</option><option>DEF</option><option>MID</option><option>ATT</option></select><button class="btn small" onclick="trainSquad()">✦ &nbsp;Team training</button></div></div><div class="table-wrap"><table class="roster"><thead><tr><th>Player</th><th>Pos</th><th>Age</th><th>OVR</th><th>Morale</th><th>Form</th><th>Value</th></tr></thead><tbody id="rosterRows">${players.map(p=>playerRow(p)).join('')}</tbody></table></div></div></section><p style="font-size:10px;color:#627277;margin:12px 3px">Player ratings and values are fictional. Click any player for details.</p>`}
function playerRow(p){return `<tr onclick="showPlayer(${p.id})" data-pos="${p.pos}"><td><div class="player-cell"><div class="player-avatar">${p.num}</div><div>${p.name}<div style="font-size:9px;color:#718186;font-weight:500">${p.flag} · #${p.num}</div></div></div></td><td><span class="position-tag">${p.pos}</span></td><td>${p.age}</td><td class="rating ${p.rating>=82?'high':''}">${p.rating}</td><td><div style="display:flex;align-items:center;gap:7px"><div class="progress"><i style="width:${p.morale}%"></i></div><span style="font-size:10px;color:#aab8b3">${p.morale}</span></div></td><td><span class="pill ${p.form==='Excellent'?'':'gold'}">${p.form}</span></td><td>${p.value}</td></tr>`}
function filterSquad(value){document.querySelectorAll('#rosterRows tr').forEach(row=>{let pos=row.dataset.pos;row.style.display=value==='all'||pos===value||(value==='DEF'&&['RB','CB','LB'].includes(pos))||(value==='MID'&&['CDM','CM','CAM'].includes(pos))||(value==='ATT'&&['RW','LW','ST'].includes(pos))?'':'none'})}
function showPlayer(id){let p=players.find(x=>x.id===id);if(!p)return;document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" onclick="if(event.target===this)this.remove()"><div class="modal"><div class="modal-head"><div><div class="eyebrow">Player profile · ${p.flag}</div><h2>${p.name}</h2></div><button class="close" onclick="this.closest('.modal-backdrop').remove()">×</button></div><div class="player-hero"><div class="player-big">${p.num}</div><div><div style="font-size:12px;color:#a7b6af">${p.pos} · ${p.age} years · #${p.num}</div><div style="font-size:23px;font-weight:850;margin-top:3px;color:var(--lime)">${p.rating} <small style="font-size:11px;color:#82928e">OVERALL</small></div></div><div style="margin-left:auto;text-align:right"><div class="muted" style="font-size:10px">Market value</div><b>${p.value}</b></div></div><div class="attrs">${[['Pace',p.pace],['Shooting',p.shoot],['Passing',p.pass],['Defending',p.def],['Physical',p.phys],['Morale',p.morale]].map(a=>`<div class="attr"><label>${a[0]}</label><b>${a[1]}</b><div class="progress" style="width:100%;margin-top:7px"><i style="width:${a[1]}%"></i></div></div>`).join('')}</div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:17px"><span class="muted" style="font-size:11px">Current form <b style="color:var(--green)">${p.form}</b></span><button class="btn" onclick="this.closest('.modal-backdrop').remove();switchPage('Tactics')">View tactics →</button></div></div></div>`)}
function tacticsPage(){let formation=state.formation;let shapes={'4-3-3':[[50,89],[18,69],[39,73],[61,73],[82,69],[29,51],[50,56],[71,51],[20,23],[50,17],[80,23]],'4-2-3-1':[[50,89],[18,69],[39,73],[61,73],[82,69],[38,54],[62,54],[20,35],[50,37],[80,35],[50,17]],'3-5-2':[[50,89],[27,71],[50,75],[73,71],[13,50],[34,54],[50,48],[66,54],[87,50],[37,22],[63,22]]};let starters=players.slice(0,11);return `<div class="page-head"><div><div class="eyebrow">Match preparation</div><h1>Team tactics</h1><p>Pick your shape, set your approach, and take control.</p></div><button class="btn primary" onclick="toast('Lineup saved for the next match')">Save changes&nbsp; ✓</button></div><div class="grid" style="grid-template-columns:minmax(0,1.3fr) minmax(270px,.8fr)"><section class="panel"><div class="panel-pad"><div class="panel-heading"><div><h2>Starting XI</h2><span class="muted" style="font-size:10px">Tap a player on the pitch to inspect</span></div><select class="select" onchange="state.formation=this.value;render()">${['4-3-3','4-2-3-1','3-5-2'].map(f=>`<option ${f===formation?'selected':''}>${f}</option>`).join('')}</select></div><div class="pitch-wrap"><div class="pitch"><div class="pitch-line"></div><div class="center-circle"></div><div class="box-top"></div><div class="box-bottom"></div>${starters.map((p,i)=>{let pt=shapes[formation][i];return `<div class="player-dot" style="left:${pt[0]}%;top:${pt[1]}%" onclick="showPlayer(${p.id})"><div class="dot-shirt">${p.num}</div><div class="player-label">${p.name.split(' ')[0]}</div><div class="player-rating">${p.rating} · ${p.pos}</div></div>`}).join('')}</div></div></div></section><div class="right-stack"><section class="panel panel-pad"><div class="panel-heading"><h2>Playing style</h2><span class="muted" style="font-size:10px">TEAM APPROACH</span></div><div class="tactic-options">${['Balanced','Pressing','Possession','Counter'].map(t=>`<button class="tactic-btn ${state.tactic===t?'selected':''}" onclick="state.tactic='${t}';render()">${t==='Balanced'?'◉':t==='Pressing'?'↗':t==='Possession'?'◎':'⚡'} &nbsp;${t}</button>`).join('')}</div><div class="divider"></div><div style="font-size:11px;color:#abb8b4"><b style="color:#e5eee8">${state.tactic}</b><br><span style="display:block;margin-top:5px">${tacticDescription()}</span></div></section><section class="panel panel-pad"><div class="panel-heading"><h2>Set-piece takers</h2><span class="muted" style="font-size:10px">AUTO PICK</span></div>${[['Captain','Luca Moretti'],['Penalties','Amir Haddad'],['Free kicks','Luca Moretti'],['Corners','Santiago Reyes']].map(x=>`<div style="display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px solid #253238;font-size:11px"><span class="muted">${x[0]}</span><b>${x[1]}</b></div>`).join('')}</section><section class="panel panel-pad"><div class="panel-heading"><h2>Team condition</h2><span class="up">● Fit</span></div><div style="display:flex;justify-content:space-between;font-size:11px;margin:9px 0"><span class="muted">Average fitness</span><b>92%</b></div><div class="progress" style="width:100%;height:6px"><i style="width:92%"></i></div><div style="display:flex;justify-content:space-between;font-size:11px;margin:14px 0 8px"><span class="muted">Team cohesion</span><b>Good</b></div><div class="progress" style="width:100%;height:6px"><i style="width:78%;background:#a5c96b"></i></div></section></div></div>`}
function tacticDescription(){return {'Balanced':'A flexible shape that keeps the team compact and ready to adapt.','Pressing':'Win the ball high with energetic pressure. Creates chances, but uses more stamina.','Possession':'Keep the ball moving and patiently find space between the lines.','Counter':'Sit in, absorb pressure, then break quickly into open space.'}[state.tactic]}
function fixturesPage(){let upcoming=[{date:`${state.day} ${state.month}`,home:'Northstar FC',away:'Eastborough',venue:'Northstar Park',next:true},{date:'Oct 26',home:'Kingsport',away:'Northstar FC',venue:'Kingsport Arena'},{date:'Nov 02',home:'Northstar FC',away:'Redbridge',venue:'Northstar Park'},{date:'Nov 09',home:'Southport',away:'Northstar FC',venue:'Southport Ground'}];return `<div class="page-head"><div><div class="eyebrow">2026 / 27 season</div><h1>Fixtures & results</h1><p>Every match is another chance to make history.</p></div><button class="btn" onclick="playMatch()">▶ &nbsp;Play next match</button></div><section class="panel"><div class="panel-pad"><div class="panel-heading"><h2>Upcoming fixtures</h2><span class="muted" style="font-size:10px">LEAGUE · MATCHWEEK ${state.played+1}</span></div>${upcoming.map((f,i)=>`<div class="fixture-card"><div class="fixture-card-date">${f.date}<small style="display:block;color:#647478;margin-top:4px">${i===0?'TODAY':'PREMIER DIVISION'}</small></div><div class="fixture-card-team"><div class="mini-crest">${f.home[0]}</div>${f.home}<span class="muted" style="font-size:10px">vs</span>${f.away}<div class="mini-crest">${f.away[0]}</div></div>${i===0?`<button class="btn primary" onclick="playMatch()">Play match →</button>`:`<span style="font-size:10px;text-align:right;color:#7e8d90">${f.venue}</span>`}</div>`).join('')}</div></section><section class="panel panel-pad section-spacer"><div class="panel-heading"><h2>Played matches</h2><span class="muted" style="font-size:10px">${state.played} MATCHES</span></div><div class="fixture-list">${state.fixtures.map(f=>fixtureRow(f)).join('')}</div></section><section class="panel panel-pad section-spacer"><div class="panel-heading"><h2>Premier Division</h2><span class="muted" style="font-size:10px">TABLE · AFTER ${state.played} MATCHES</span></div><div class="table-wrap"><table class="roster"><thead><tr><th>Pos</th><th>Club</th><th>MP</th><th>W</th><th>D</th><th>L</th><th>GD</th><th>Pts</th></tr></thead><tbody>${[['Eastborough',state.points+2,'E'],['Northstar FC',state.points,'N'],['Kingsport',state.points-1,'K'],['Redbridge',state.points-2,'R'],['Westhaven',state.points-4,'W']].map((r,i)=>`<tr style="cursor:default"><td>${i+1}</td><td><div class="player-cell"><div class="mini-crest">${r[2]}</div>${r[0]}</div></td><td>${state.played}</td><td>${i===1?state.wins:state.wins-1}</td><td>${state.draws}</td><td>${state.losses}</td><td>+${state.for-state.against}</td><td><b>${r[1]}</b></td></tr>`).join('')}</tbody></table></div></section>`}
const targets=[{name:'Dario Kovac',pos:'AM',age:20,rating:76,value:9.5,flag:'CRO'},{name:'Ethan Brooks',pos:'LB',age:22,rating:75,value:7,flag:'ENG'},{name:'Youssef Amrani',pos:'ST',age:19,rating:73,value:6.5,flag:'MAR'}];
function transfersPage(){return `<div class="page-head"><div><div class="eyebrow">Recruitment centre</div><h1>Transfers</h1><p>Shape the future of Northstar. Every signing counts.</p></div><div class="date-chip">Available budget &nbsp;<b style="color:var(--lime)">€${state.budget.toFixed(1)}m</b></div></div><div class="squad-summary"><div class="summary-chip"><span>Transfer budget</span><strong>€${state.budget.toFixed(1)}m</strong></div><div class="summary-chip"><span>Wage budget</span><strong>€82k <small class="muted" style="font-size:10px">/ week</small></strong></div><div class="summary-chip"><span>Scouted prospects</span><strong>${targets.length}</strong></div><div class="summary-chip"><span>Window closes</span><strong>Jan 31</strong></div></div><div class="grid" style="grid-template-columns:minmax(0,1.3fr) minmax(270px,.8fr)"><section class="panel panel-pad"><div class="panel-heading"><div><h2>Scouting shortlist</h2><span class="muted" style="font-size:10px">Promising players identified by your scouts</span></div><button class="btn small" onclick="toast('Scouts are searching for new talent…')">⌕ &nbsp;Scout</button></div>${targets.map((p,i)=>`<div class="market-card"><div class="player-avatar" style="height:38px;width:38px">${p.flag[0]}${p.flag[1]}</div><div class="market-info"><strong>${p.name}</strong><span>${p.pos} · ${p.age} years · ${p.flag} · Rating ${p.rating}</span></div><div class="market-price">€${p.value}m</div><button class="btn small ${state.budget>=p.value?'primary':''}" onclick="signPlayer(${i})">Sign</button></div>`).join('')}<div class="empty-note" style="padding:16px 0 0">New scouting reports arrive as your season progresses.</div></section><div class="right-stack"><section class="panel panel-pad"><div class="panel-heading"><h2>Transfer-listed</h2><span class="muted" style="font-size:10px">YOUR SQUAD</span></div>${state.transferList.length?state.transferList.map(id=>{let p=players.find(x=>x.id===id);return p?`<div class="market-card"><div class="player-avatar">${p.num}</div><div class="market-info"><strong>${p.name}</strong><span>${p.pos} · ${p.rating} OVR</span></div><div class="market-price">${p.value}</div><button class="btn small" onclick="removeListing(${p.id})">×</button></div>`:''}).join(''):'<div class="empty-note">No players listed for transfer.<br><small>List a player from their profile.</small></div>'}</section><section class="panel panel-pad"><div class="panel-heading"><h2>Market activity</h2><span class="pulse">● LIVE</span></div><div class="feed-item"><div class="feed-icon">⌕</div><div class="feed-text"><b>Scout network expanded</b><small>3 players added to your shortlist.</small></div></div><div class="feed-item"><div class="feed-icon" style="background:#2b2c25;color:var(--gold)">€</div><div class="feed-text"><b>Budget available</b><small>Board expects smart recruitment this season.</small></div></div></section></div></div>`}
function signPlayer(i){let p=targets[i];if(!p||state.budget<p.value){toast('Not enough transfer budget for this signing.');return}if(players.some(x=>x.name===p.name)){toast('This player is already at the club.');return}state.budget-=p.value;players.push({id:Date.now(),name:p.name,pos:p.pos,num:players.length+1,rating:p.rating,age:p.age,flag:p.flag,value:`€${p.value}m`,pace:78,shoot:72,pass:74,def:65,phys:70,morale:82,form:'Good'});toast(`${p.name} signed for Northstar!`)}
function removeListing(id){state.transferList=state.transferList.filter(x=>x!==id);toast('Player removed from transfer list.')}
function trainSquad(){players.forEach(p=>{p.morale=Math.min(99,p.morale+2);if(Math.random()<.2)p.rating=Math.min(99,p.rating+1)});state.morale=Math.min(99,state.morale+3);toast('Training complete — morale and sharpness improved!')}
function switchPage(page){state.page=page;state.toast='';render();window.scrollTo(0,0)}
function playMatch(){let strength=players.slice(0,11).reduce((a,p)=>a+p.rating,0)/11;let tacticsBonus=state.tactic==='Pressing'?.35:state.tactic==='Possession'?.2:state.tactic==='Counter'?.15:0;let ours=Math.max(0,Math.floor(Math.random()*4+(strength-78)/12+tacticsBonus));let theirs=Math.floor(Math.random()*3+(Math.random()<.2?1:0));if(state.tactic==='Counter'&&Math.random()<.18)ours++;let win=ours>theirs,draw=ours===theirs;state.played++;if(win){state.wins++;state.points+=3;state.morale=Math.min(99,state.morale+3)}else if(draw){state.draws++;state.points++;state.morale=Math.max(40,state.morale-1)}else{state.losses++;state.morale=Math.max(40,state.morale-4)}state.for+=ours;state.against+=theirs;let events=[];let scorers=players.filter(p=>['ST','RW','LW','CM'].includes(p.pos)).sort(()=>Math.random()-.5);for(let n=0;n<ours;n++){let p=scorers[n%scorers.length];events.push({time:12+n*24+Math.floor(Math.random()*10),text:`${p.name} finds the net for Northstar!`})}if(theirs)events.push({time:34+Math.floor(Math.random()*42),text:'Eastborough pull one back.'});events.sort((a,b)=>a.time-b.time);let outcome=win?'A brilliant result — the supporters are delighted!':draw?'A hard-fought point. We move on.':'A difficult result. The team will bounce back.';state.fixtures.unshift({date:`${state.month} ${state.day}`,home:'Northstar',away:'Eastborough',score:`${ours} – ${theirs}`,result:win?'W':draw?'D':'L'});state.fixtures=state.fixtures.slice(0,8);state.day+=7;if(state.day>30){state.day-=30;state.month=state.month==='October'?'November':state.month==='November'?'December':'January'}let page=state.page;render();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop"><div class="modal match-modal"><div class="match-head">FULL TIME · PREMIER DIVISION</div><div style="display:flex;justify-content:center;align-items:center;gap:20px;margin-top:18px"><div class="team-lockup"><div class="team-crest">N</div>Northstar FC</div><div class="scoreline">${ours} : ${theirs}</div><div class="team-lockup"><div class="team-crest away">E</div>Eastborough</div></div><div style="color:#a5b2ae;font-size:12px">${outcome}</div><div class="event-list">${events.length?events.map(e=>`<div class="event"><time>${e.time}'</time><span>${e.text}</span></div>`).join(''):'<div class="event"><time>90\'</time><span>A tight, goalless encounter. Both defences stood firm.</span></div>'}</div><button class="btn primary" style="width:100%" onclick="this.closest('.modal-backdrop').remove();render()">Continue&nbsp; →</button></div></div>`)}
function render(){document.querySelector('#app').innerHTML=shell();document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>switchPage(b.dataset.page));let nav=document.createElement('nav');nav.className='bottom-nav';nav.innerHTML=navItems.map(([n,i])=>`<button data-mobile="${n}" class="${state.page===n?'active':''}"><span class="nav-icon">${i}</span>${n}</button>`).join('');document.body.appendChild(nav);document.querySelectorAll('[data-mobile]').forEach(b=>b.onclick=()=>switchPage(b.dataset.mobile));document.querySelectorAll('.bottom-nav:not(:last-child)').forEach(n=>n.remove())}
render();
</script></body></html>

