+++ index.html
@@ -34,5 +34,21 @@
 function shell(){return `<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">T</div><div><div class="brand-title">TOUCHLINE</div><div class="brand-sub">Football director</div></div></div><div class="club-card"><div class="club-top"><div class="crest">N</div><div><div class="club-name">Northstar FC</div><div class="club-league">Premier Division · 3rd</div></div></div><div class="club-meta"><span>Transfer budget<br><b>€${state.budget.toFixed(1)}m</b></span><span style="text-align:right">Season<br><b>2026 / 27</b></span></div></div><div><div class="nav-label">CLUB</div><nav class="nav">${navItems.map(([n,i])=>`<button data-page="${n}" class="${state.page===n?'active':''}"><span class="nav-icon">${i}</span>${n}</button>`).join('')}</nav></div><div class="side-bottom"><div class="season-card"><strong>◉ Board confidence <span style="float:right;color:var(--lime)">${state.morale}%</span></strong><span>Keep the momentum going.</span><div style="height:4px;background:#27343a;border-radius:9px;margin-top:10px"><div style="height:100%;width:${state.morale}%;background:var(--lime);border-radius:9px"></div></div></div><div style="padding:16px 10px 0;color:#56666a;font-size:10px">TOUCHLINE 1.0 <span style="float:right">● LIVE</span></div></div></aside><main class="main"><header class="topbar"><div class="crumb">Club <span style="margin:0 7px;color:#546267">/</span><b>${state.page}</b></div><div class="top-actions"><div class="date-chip">◷ &nbsp;${state.day} ${state.month} ${state.season}</div><div class="avatar">JM</div></div></header><div class="content">${pageContent()}</div></main></div>${state.toast?`<div class="toast">✓ &nbsp;${state.toast}</div>`:''}`}
 function pageContent(){switch(state.page){case'Squad':return squadPage();case'Tactics':return tacticsPage();case'Fixtures':return fixturesPage();case'Transfers':return transfersPage();default:return overviewPage()}}
 function overviewPage(){let sorted=[['Eastborough',19,'E'],['Northstar FC',17,'N'],['Kingsport',16,'K'],['Redbridge',15,'R'],['Westhaven',13,'W']];return `<div class="page-head"><div><div class="eyebrow">Monday, ${state.day} ${state.month} ${state.season}</div><h1>Good morning, gaffer.</h1><p>Here’s what’s happening at Northstar today.</p></div><button class="btn" onclick="switchPage('Fixtures')">View calendar&nbsp; ↗</button></div><div class="overview-grid grid"><div><section class="hero"><div class="hero-inner"><div class="match-tag"><span class="dot"></span> NEXT MATCH · LEAGUE</div><h2>Ready for the next challenge?</h2><p>Keep your run going. Three points could take us to the top.</p><div class="match-visual"><div class="team-lockup"><div class="team-crest">N</div>Northstar FC</div><span class="versus">VS</span><div class="team-lockup"><div class="team-crest away">E</div>Eastborough</div><div class="match-detail">Today · 19:45<br>Home · Northstar Park</div><button class="btn primary hero-cta" onclick="playMatch()">Play match&nbsp; →</button></div></div></section><div class="stat-grid"><div class="stat"><div class="stat-label">League position</div><div class="stat-value stat-accent">3rd</div><div class="stat-foot">↑ 1 place this week</div></div><div class="stat"><div class="stat-label">Points</div><div class="stat-value">${state.points}</div><div class="stat-foot">${state.played} matches played</div></div><div class="stat"><div class="stat-label">Goals scored</div><div class="stat-value">${state.for}</div><div class="stat-foot">+${state.for-state.against} goal difference</div></div><div class="stat"><div class="stat-label">Team morale</div><div class="stat-value">${state.morale}<span style="font-size:13px;color:#82928e">%</span></div><div class="stat-foot up">▲ Squad feeling positive</div></div></div><section class="panel panel-pad"><div class="panel-heading"><h2>Recent form</h2><span class="muted" style="font-size:11px">Last 5 matches</span></div><div class="fo