</th></tr></thead><tbody>${[['Eastborough',state.points+2,'E'],['Northstar FC',state.points,'N'],['Kingsport',state.points-1,'K'],['Redbridge',state.points-2,'R'],['Westhaven',state.points-4,'W']].map((r,i)=>`<tr style="cursor:default"><td>${i+1}</td><td><div class="player-cell"><div class="mini-crest">${r[2]}</div>${r[0]}</div></td><td>${state.played}</td><td>${i===1?state.wins:state.wins-1}</td><td>${state.draws}</td><td>${state.losses}</td><td>+${state.for-state.against}</td><td><b>${r[1]}</b></td></tr>`).join('')}</tbody></table></div></section>`}
