 function transfersPage(){return `<div class="page-head"><div><div class="eyebrow">Recruitment centre</div><h1>Transfers</h1><p>Shape the future of Northstar. Every signing counts.</p></div><div class="date-chip">Available budget &nbsp;<b style="color:var(--lime)">€${state.budget.toFixed(1)}m</b></div></div><div class="squad-summary"><div class="summary-chip"><span>Transfer budget</span><strong>€${state.budget.toFixed(1)}m</strong></div><div class="summary-chip"><span>Wage budget</span><strong>€82k <small class="muted" style="font-size:10px">/ week</small></strong></div><div class="summary-chip"><span>Scouted prospects</span><strong>${targets.length}</strong></div><div class="summary-chip"><span>Window closes</span><strong>Jan 31</strong></div></div><div class="grid" style="grid-template-columns:minmax(0,1.3fr) minmax(270px,.8fr)"><section class="panel panel-pad"><div class="panel-heading"><div><h2>Scouting shortlist</h2><span class="muted" style="font-size:10px">Promising players identified by your scouts</span></div><button class="btn small" onclick="toast('Scouts are searching for new talent…')">⌕ &nbsp;Scout</button></div>${targets.map((p,i)=>`<div class="market-card"><div class="player-avatar" style="height:38px;width:38px">${p.flag[0]}${p.flag[1]}</div><div class="market-info"><strong>${p.name}</strong><span>${p.pos} · ${p.age} years · ${p.flag} · Rating ${p.rating}</span></div><div class="market-price">€${p.value}m</div><button class="btn small ${state.budget>=p.value?'primary':''}" onclick="signPlayer(${i})">Sign</button></div>`).join('')}<div class="empty-note" style="padding:16px 0 0">New scouting reports arrive as your season progresses.</div></section><div class="right-stack"><section class="panel panel-pad"><div class="panel-heading"><h2>Transfer-listed</h2><span class="muted" style="font-size:10px">YOUR SQUAD</span></div>${state.transferList.length?state.transferList.map(id=>{let p=players.find(x=>x.id===id);return p?`<div class="market-card"><div class="player-avatar">${p.num}</div><div class="market-info"><strong>${p.name}</strong><span>${p.pos} · ${p.rating} OVR</span></div><div class="market-price">${p.value}</div><button class="btn small" onclick="removeListing(${p.id})">×</button></div>`:''}).join(''):'<div class="empty-note">No players listed for transfer.<br><small>List a player from their profile.</small></div>'}</section><section class="panel panel-pad"><div class="panel-heading"><h2>Market activity</h2><span class="pulse">● LIVE</span></div><div class="feed-item"><div class="feed-icon">⌕</div><div class="feed-text"><b>Scout network expanded</b><small>3 players added to your shortlist.</small></div></div><div class="feed-item"><div class="feed-icon" style="background:#2b2c25;color:var(--gold)">€</div><div class="feed-text"><b>Budget available</b><small>Board expects smart recruitment this season.</small></div></div></section></div></div>`}
 function signPlayer(i){let p=targets[i];if(!p||state.budget<p.value){toast('Not enough transfer budget for this signing.');return}if(players.some(x=>x.name===p.name)){toast('This player is already at the club.');return}state.budget-=p.value;players.push({id:Date.now(),name:p.name,pos:p.pos,num:players.length+1,rating:p.rating,age:p.age,flag:p.flag,value:`€${p.value}m`,pace:78,shoot:72,pass:74,def:65,phys:70,morale:82,form:'Good'});toast(`${p.name} signed for Northstar!`)}
